function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function on(p){return p?.templateId==='hospitality'||(p?.modules||[]).includes('hospitality_core')}
function html(p){const name=esc(p.company?.name||'La tua struttura');return `<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#171713"><title>${name} · Easy Come Hospitality</title><link rel="manifest" href="manifest.webmanifest"><link rel="stylesheet" href="assets/hospitality.css"></head><body><div id="hospitalityApp"></div><script src="js/config.js"></script><script>if(window.APP_CONFIG&&window.APP_CONFIG.dataMode==='cloud'){document.write('<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"><\/script>')}</script><script src="js/hospitality.js"></script><script>if('serviceWorker' in navigator&&location.protocol!=='file:'){addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}))}</script></body></html>`}
function alias(hash){return `<!doctype html><meta charset="utf-8"><script>location.replace('index.html#${hash}')</script><p><a href="index.html#${hash}">Apri Easy Come Hospitality</a></p>`}
function files(project){if(!on(project))return[];const manifest=JSON.stringify({name:`${project.company?.name||'Struttura'} · Easy Come`,short_name:'Easy Come',start_url:'./index.html#today',display:'standalone',background_color:'#f3efe7',theme_color:'#171713',icons:[{src:'assets/favicon.svg',sizes:'any',type:'image/svg+xml',purpose:'any maskable'}]},null,2);const sw=`const CACHE='easycome-hospitality-v2-final';const ASSETS=['./','./index.html','./manuale.html','./assets/hospitality.css','./assets/favicon.svg','./js/config.js','./js/hospitality.js'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request)))})`;return [{name:'index.html',data:html(project)},{name:'frontdesk.html',data:alias('today')},{name:'gestionale.html',data:alias('today')},{name:'performance.html',data:alias('numbers')},{name:'channels.html',data:alias('operations:channels')},{name:'intelligence.html',data:alias('numbers')},{name:'easycome-hub.html',data:alias('hub')},{name:'manifest.webmanifest',data:manifest},{name:'sw.js',data:sw},{name:'assets/hospitality.css',data:APP_CSS},{name:'js/hospitality.js',data:APP_JS},{name:'CHANNELS/README.md',data:'# Canali esterni\n\nLe connessioni calendario e gli eventuali provider OTA vengono configurati durante l’implementazione. Nel gestionale il gestore vede solo stato, disponibilità e risultato operativo.\n'}]}
function previewHtml(project){const p=JSON.parse(JSON.stringify(project||{}));p.organizationId='preview-'+String(p.organizationId||'easycome').slice(0,24);p.entities=p.entities||[];const config={project:p,dataMode:'local',previewMode:true};const safe=JSON.stringify(config).replace(/</g,'\u003c');return `<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${APP_CSS}</style></head><body><div id="hospitalityApp"></div><script>window.APP_CONFIG=${safe};<\/script><script>${APP_JS.replace(/<\/script/gi,'<\\/script')}<\/script></body></html>`}
global.ECHospitalityTemplates={files,previewHtml};
